-- What a challan paid is written once and stays.
CREATE FUNCTION app.refuse_tax_challan_change() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'what a challan paid is never changed or removed' USING ERRCODE = 'SE379';
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.refuse_tax_challan_change() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER challan_expense_entries_keep
  BEFORE UPDATE OR DELETE ON public.challan_expense_entries
  FOR EACH ROW EXECUTE FUNCTION app.refuse_tax_challan_change();
--> statement-breakpoint
ALTER TABLE public.challan_expense_entries ENABLE ALWAYS TRIGGER challan_expense_entries_keep;
--> statement-breakpoint
CREATE TRIGGER challan_payroll_runs_keep
  BEFORE UPDATE OR DELETE ON public.challan_payroll_runs
  FOR EACH ROW EXECUTE FUNCTION app.refuse_tax_challan_change();
--> statement-breakpoint
ALTER TABLE public.challan_payroll_runs ENABLE ALWAYS TRIGGER challan_payroll_runs_keep;
