-- ── hand-written: recording a challan that pays any of the three ────────────────────────────────
-- Tax paid to the government out of a cash or bank account: debit the withholding payable
-- account of its kind, credit the account. It pays whole amounts of its own kind, each once:
-- tax withheld on supplier bills (as app.record_withholding_challan does, with the same
-- questions), tax withheld on expenses that stand, and, for income tax, the tax approved
-- payroll runs deducted from pay. Its amount is theirs. It belongs to the whole company, so
-- only a member who works in every branch records one. Returns its number.
CREATE FUNCTION app.record_tax_challan(p_kind text, p_paid_on date, p_account uuid, p_challan_no text, p_bill_entries uuid[], p_expense_entries uuid[], p_runs uuid[], p_note text DEFAULT NULL) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_bills uuid[] := coalesce(p_bill_entries, '{}'::uuid[]);
  v_expenses uuid[] := coalesce(p_expense_entries, '{}'::uuid[]);
  v_runs uuid[] := coalesce(p_runs, '{}'::uuid[]);
  v_control text;
  v_account text;
  v_challan_no text := nullif(btrim(p_challan_no), '');
  v_bill_count integer;
  v_bill_amount numeric;
  v_expense_count integer;
  v_expense_amount numeric;
  v_run_count integer;
  v_run_amount numeric;
  v_amount numeric;
  v_id uuid := gen_random_uuid();
  v_number text;
  v_journal uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'this member cannot record a challan' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'a challan is recorded in a read committed transaction' USING ERRCODE = 'SE379';
  END IF;
  v_control := CASE p_kind WHEN 'income_tax' THEN 'wht_income_tax' WHEN 'sales_tax' THEN 'wht_sales_tax' WHEN 'provincial_sales_tax' THEN 'wht_provincial_tax' END;
  IF v_control IS NULL OR v_challan_no IS NULL OR char_length(v_challan_no) > 60
     OR cardinality(v_bills) + cardinality(v_expenses) + cardinality(v_runs) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'a challan is of one kind of tax, has a number, and pays between 1 and 500 amounts' USING ERRCODE = 'SE379';
  END IF;
  -- Tax deducted from pay is income tax (section 149).
  IF cardinality(v_runs) > 0 AND p_kind <> 'income_tax' THEN
    RAISE EXCEPTION 'tax deducted from salaries is income tax' USING ERRCODE = 'SE379';
  END IF;
  IF p_paid_on IS NULL OR NOT isfinite(p_paid_on) OR p_paid_on > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE333';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_paid_on);
  v_account := app.paying_account(v_tenant, p_account);

  -- What it pays is held, each kind of row in one order, so that two challans cannot pay the
  -- same one; and each expense is held, so that it cannot be cancelled while its tax is paid.
  PERFORM 1 FROM public.withholding_entries e WHERE e.tenant_id = v_tenant AND e.id = ANY (v_bills) ORDER BY e.id FOR UPDATE;
  PERFORM 1 FROM public.expenses e
    WHERE e.tenant_id = v_tenant AND e.id IN (SELECT x.expense_id FROM public.expense_withholdings x WHERE x.tenant_id = v_tenant AND x.id = ANY (v_expenses))
    ORDER BY e.id FOR UPDATE;
  PERFORM 1 FROM public.expense_withholdings x WHERE x.tenant_id = v_tenant AND x.id = ANY (v_expenses) ORDER BY x.id FOR UPDATE;
  PERFORM 1 FROM public.payroll_runs r WHERE r.tenant_id = v_tenant AND r.id = ANY (v_runs) ORDER BY r.id FOR UPDATE;

  -- Tax withheld on supplier bills: the questions of app.record_withholding_challan.
  SELECT count(*), coalesce(sum(e.amount), 0) INTO v_bill_count, v_bill_amount FROM public.withholding_entries e
    WHERE e.tenant_id = v_tenant AND e.id = ANY (v_bills) AND e.kind = p_kind AND e.entry_date <= p_paid_on
      AND NOT EXISTS (SELECT 1 FROM public.withholding_challan_entries c WHERE c.tenant_id = e.tenant_id AND c.entry_id = e.id);
  -- Tax withheld on an expense that stands (a cancelled one has given its tax back).
  SELECT count(*), coalesce(sum(x.amount), 0) INTO v_expense_count, v_expense_amount FROM public.expense_withholdings x
    JOIN public.expenses e ON e.tenant_id = x.tenant_id AND e.id = x.expense_id
    WHERE x.tenant_id = v_tenant AND x.id = ANY (v_expenses) AND x.kind = p_kind AND x.entry_date <= p_paid_on AND e.status = 'posted'
      AND NOT EXISTS (SELECT 1 FROM public.challan_expense_entries c WHERE c.tenant_id = x.tenant_id AND c.entry_id = x.id);
  -- The tax an approved payroll run deducted from pay, whole and to the paisa, once its journal's day has come.
  SELECT count(*), coalesce(sum(r.tax), 0) INTO v_run_count, v_run_amount FROM public.payroll_runs r
    WHERE r.tenant_id = v_tenant AND r.id = ANY (v_runs) AND r.status IN ('approved', 'paid') AND r.tax > 0 AND r.tax = round(r.tax, 2) AND r.journal_date <= p_paid_on
      AND NOT EXISTS (SELECT 1 FROM public.challan_payroll_runs c WHERE c.tenant_id = r.tenant_id AND c.run_id = r.id);
  IF v_bill_count <> cardinality(v_bills) OR v_bill_count <> (SELECT count(DISTINCT x) FROM unnest(v_bills) AS x)
     OR v_expense_count <> cardinality(v_expenses) OR v_expense_count <> (SELECT count(DISTINCT x) FROM unnest(v_expenses) AS x)
     OR v_run_count <> cardinality(v_runs) OR v_run_count <> (SELECT count(DISTINCT x) FROM unnest(v_runs) AS x) THEN
    RAISE EXCEPTION 'a challan pays whole amounts of its own kind, withheld or deducted on or before its date, each once' USING ERRCODE = 'SE379';
  END IF;
  v_amount := v_bill_amount + v_expense_amount + v_run_amount;
  IF v_amount <= 0 OR v_amount <> round(v_amount, 2) THEN
    RAISE EXCEPTION 'what a challan pays comes to an amount in rupees and paisa, above nothing' USING ERRCODE = 'SE379';
  END IF;
  v_amount := round(v_amount, 2);

  v_number := app.next_document_number('WC', p_paid_on);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_paid_on, 'withholding_challan', v_id, v_number, left('Tax withheld paid under challan ' || v_challan_no, 500), NULL, v_user)
    RETURNING id INTO v_journal;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, 1, app.control_account(v_tenant, v_control), v_amount, 0, 'Challan ' || v_challan_no),
           (v_tenant, v_journal, 2, p_account, 0, v_amount, 'Challan ' || v_challan_no);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_paid_on, 'source', 'withholding_challan', 'sourceId', v_id, 'number', v_number, 'lines', 2, 'total', v_amount::text));
  INSERT INTO public.withholding_challans (id, tenant_id, number, kind, challan_no, paid_on, account_id, amount, note, journal_id, created_by)
    VALUES (v_id, v_tenant, v_number, p_kind, v_challan_no, p_paid_on, p_account, v_amount, nullif(btrim(p_note), ''), v_journal, v_user);
  INSERT INTO public.withholding_challan_entries (tenant_id, challan_id, entry_id)
    SELECT v_tenant, v_id, x FROM unnest(v_bills) AS x;
  INSERT INTO public.challan_expense_entries (tenant_id, challan_id, entry_id)
    SELECT v_tenant, v_id, x FROM unnest(v_expenses) AS x;
  INSERT INTO public.challan_payroll_runs (tenant_id, challan_id, run_id, amount)
    SELECT v_tenant, v_id, r.id, r.tax FROM public.payroll_runs r WHERE r.tenant_id = v_tenant AND r.id = ANY (v_runs);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'withholding_challan.record', 'withholding_challan', v_id,
      jsonb_build_object('number', v_number, 'kind', p_kind, 'challan', v_challan_no, 'date', p_paid_on, 'account', v_account, 'amount', v_amount::text,
        'entries', v_bill_count, 'expenseEntries', v_expense_count, 'payrollRuns', v_run_count, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.record_tax_challan(text, date, uuid, text, uuid[], uuid[], uuid[], text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.record_tax_challan(text, date, uuid, text, uuid[], uuid[], uuid[], text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: an expense whose tax has been paid over stands ────────────────────────────────
-- A trigger of this track's own on its own table. app.cancel_expense holds the expense before
-- it changes it, and a challan holds the expenses whose tax it pays, so the two cannot pass
-- each other.
CREATE FUNCTION app.check_expense_tax_paid_over() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'posted' AND NEW.status IS DISTINCT FROM 'posted' AND EXISTS (
       SELECT 1 FROM public.challan_expense_entries c
       JOIN public.expense_withholdings x ON x.tenant_id = c.tenant_id AND x.id = c.entry_id
       WHERE x.tenant_id = OLD.tenant_id AND x.expense_id = OLD.id) THEN
    RAISE EXCEPTION 'tax withheld on this expense has been paid over under a challan, so the expense stands' USING ERRCODE = 'SE380';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_expense_tax_paid_over() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER expenses_tax_paid_over
  BEFORE UPDATE ON public.expenses
  FOR EACH ROW EXECUTE FUNCTION app.check_expense_tax_paid_over();
--> statement-breakpoint
ALTER TABLE public.expenses ENABLE ALWAYS TRIGGER expenses_tax_paid_over;
